"""Persist reviewed Rust bodies and bounded claims; unresolved scope stays explicit."""
import hashlib,json,re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];REV=ROOT/'dag/reviews';PREFIX='additional_rust_category_remaining'
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
scope=json.loads((REV/(PREFIX+'_scope.json')).read_text());by={r['path']:r for r in scope['files']}
base='code/rust/core_category_theory/'
notes={
 'src/condensation.rs':'Complete434-line body covered by residual reading and exact renamed capacity blocks. Stores splitting labels and caller-supplied verified flags; checks three strict named composition equations and flags only at positive levels. It does not verify cell boundaries, actual homotopies, coherence equations, level coverage or exhaustive condensations; Complete means the supplied finite list passed, and Unknown is never produced. The unverified base flag is ignored by validation, while fully_verified uses all flags; max_verified_level does not certify a contiguous verified tower. No infinity-category/completeness or representability theorem is implemented. All tests covered.',
 'src/limits.rs':'Complete631-line body covered by residual reading and exact renamed capacity blocks. Contains substantive exhaustive finite mediator uniqueness searches for products/equalizers/pullbacks, conditional on a complete lawful ambient category and correctly typed diagram. Product checks its cone and recomputes universal witnesses rather than trusting the supplied map. Equalizer target metadata is unused; pullback lacks object/leg-boundary admission, allowing nonexistent source/apex labels to evade mediator enumeration. check_terminal lacks membership admission and accepts any label in the empty category. General cones index legs by ambient object, so repeated diagram occurrences cannot have distinct legs. Capacity tests do not exercise these laws.',
 'src/colimits.rs':'Complete612-line body covered by residual reading and exact renamed capacity blocks. Dual finite cocone and exhaustive mediator checks are meaningful on an admitted lawful category and typed diagram. Coproduct checks its cocone; coequalizer source metadata is unused; pushout omits object/injection-boundary admission, enabling a vacuous nonexistent-object case. check_initial accepts any nonexistent label when the ambient category is empty. No full category admission is invoked. Ambient-object-keyed legs cannot represent repeated diagram occurrences independently. Capacity tests only check count records, not colimit semantics.',
 'src/nerve.rs':'Complete787-line body covered by residual reading and exact renamed capacity blocks. Legacy DeclaredNerve implements chain/face/identity-insertion formulas under an explicit lawful-category premise, but malformed empty Chain can panic and arbitrary chains are not admitted. ValidatedFiniteNerve repairs that boundary: canonical validated category required, full simplex membership/composability checked, dimension<=32 and complete degree/cell enumeration or refusal. map_simplex requires exact source/target declarations matching the functor token, so separately validated carriers prevent the earlier raw-functor-carrier omission from propagating here. Bounded paths retain identities and are not homotopy quotients. All substantive face/degeneracy tests read, not executed; no Kan, homotopy classification or physical lift claim.',
 'src/rewriting.rs':'Complete1064-line body read in two numbered ranges1..530 and531..1064. Implements finite named rewrite graph/path bookkeeping, formal inverse path syntax, conditional whiskering, finite reachability and cycle detection. It supplies neither higher composition laws nor invertibility/coherence evidence sufficient for an infinity-category. Validator checks many references but a level2 cell added outside the homotopies map need not have parallel paths; its public declared field also permits direct construction/mutation bypass. Local-confluence routine accepts declared homotopies between zigzags containing inverse steps, so success is weaker than directed local confluence. Termination DFS is exact for a well-formed finite forward graph; a normal-form witness only means no outgoing declared1-cell. All tests and capacity boilerplate read.',
 'src/lawvere.rs':'Complete331-line body covered by residual reading and exact renamed capacity blocks. Public syntax metadata stores sorts, operations, equations and partial substitution strings; equations are not parsed or enforced and product/projection structure is absent. Associativity checks only supplied cases, with unchecked slot addition. Cauchy test searches named unary idempotents/pairs without typing the splitting pair; constructor status defaults Complete. The headline identification with a Cauchy-complete monoid in Prof omits the defining finite-power structure. This is a partial presentation/case checker, not an admitted Lawvere theory. All tests covered.',
 'src/higher.rs':'Complete355-line body read. TwoCategory trait declares operations/laws but enforces no equations. ValidatedFiniteTwoCategory::try_new is explicitly a placeholder returning Ok for every declaration; even one object with no identity is admitted. Accessors then use unreachable on missing names/identities. Composition is bare table lookup without boundary checks. Separate interchange checker genuinely compares the supplied composite results after partial endpoint checks, conditional on lawful input operations; it does not repair the constructor. Sole embedded mutation-named test uses literal Results.',
 'src/higher_functor.rs':'Complete572-line body covered by residual reading and exact renamed capacity blocks. Strict/pseudo/lax interfaces state correct direction conventions but traits carry no enforced laws. Boundary functions check all rows of supplied boundary tables, not complete source/target categories, extra maps or composition/identity preservation. Coherence-cell check verifies listed names exist only; inverse round trips, naturality, full coherence coverage and pentagon/triangle laws are explicitly left elsewhere. InvertibleTwoMor is a public pair, not an invertibility certificate. All lookup/boundary/missing-name and capacity tests covered.',
 'src/cauchy.rs':'Complete500-line body covered by residual reading and exact renamed capacity blocks. Conditional finite idempotent detection and splitting-equation search are useful on a complete lawful category inventory, but supplied identity flags, boundary lists and tables are not validated. validate_splitting checks three named equations and a retract identity only; carrier is never consulted, so a nonexistent carrier label still receives the private validated wrapper. CauchyCompletion is a result DTO only, with no category completion algorithm here. All embedded positive/negative and capacity tests covered.',
 'src/coend.rs':'Complete458-line body covered by residual reading and exact renamed capacity blocks. Computes equivalence closure of diagonal pairs whose two supplied actions land at the same off-diagonal index. This has the wrong variance for the claimed coend: it uses common targets in F(c,c-prime), whereas coend relations come from common source elements in F(c-prime,c). Hom on the walking-arrow category is a concrete disagreement, and its positive test enshrines that merge. Input validation checks presence only; compute bypasses it and silently skips missing data. class_of also stores raw union-find roots rather than dense indices into classes. Dinaturality replay repeats the wrong relation and does not prove quotient universality. All tests covered.',
 'src/finite_joint_dynamics.rs':'Complete290-line body read. Validates nonempty duplicate-free admitted state-pair relation, local/interaction operation tables and checked count budget. A locally defined move leaving the relation is NotClosed, not silently converted into unavailability. Reports are paired local future-equivalence classes; joint Moore refinement detects added future distinctions and returns a distinguishing word. Replay recomputes the immutable admitted system but does not authenticate external declarations. Interaction semantics are supplied premises. Sole embedded mutation-named test uses literal Results.',
 'src/finite_partial_structure.rs':'Complete339-line body read. Validates many-sorted finite partial-operation and Boolean-predicate tables, then requires total surjective sort maps. Product-row descent distinguishes unseen fibers from genuine None, requires both definedness and output-class constancy, and preserves both truth and falsity. Surjectivity gives existence of representatives and uniqueness of each target row. Nullary/empty sorts handled explicitly; checked product cardinality may conservatively refuse intermediate overflow. Reverification regenerates every target field. All substantive embedded conflict, exhaustive finite, empty and composition tests read; no execution.',
 'src/finite_simulation.rs':'Complete210-line body read. Exact simulation checks common numeric reports and every source step against an explicit target event word, reflecting availability. ResourceExtension additionally requires an injective state map and records newly enabled source coordinates while preserving every old defined step. Shared label meaning is an explicit external premise. verify_simulation can correctly replay a mismatch decision; only Checked is positive evidence. Bounds are cell estimates after map/encoding validation, not byte/time limits. Sole embedded mutation-named test uses literal Results.',
 'src/finite_path.rs':'Complete228-line body read. Builds the complete free path category of an admitted nonempty finite acyclic multigraph, retaining parallel edge indices. Kahn cycle check precedes breadth-first enumeration; path-budget exhaustion refuses instead of yielding a truncated category. Concatenation includes identities and all composable pairs, followed by canonical complete category validation. Objects/edges/paths capped at64; no claim that arbitrary cyclic graph free categories are finite. Sole embedded mutation-named test uses literal Results.',
 'src/finite_independence.rs':'Complete297-line body covered by complete residual reading and exact renamed capacity blocks. State-relative swap requires both orders available and their endpoints equal in the full future quotient; raw endpoint equality is unnecessary. Non-equivalence can carry a checked distinguishing future; search exhaustion is refusal. Replay recomputes endpoints and equivalence or replays a valid, not necessarily shortest, distinction. Both unavailable orders never count as independence. No spacelike causality or context-free independence relation is inferred; repeated capacity tests are separate.',
 'src/finite_report_repair.rs':'Complete257-line body read. Witness-guided refinement splits one current report class using an already supplied distinguishing question, preserving the old report. Every legal step strictly refines without separating equal complete answer profiles. Complete verifier replays any legal witness order and independently checks the defining old-report-plus-all-answers equivalence, rejecting excessive splits and unresolved collisions. Prefix replay explicitly makes no sufficiency claim. Bounds count rows/questions/steps/pair inspections. This repairs a representation over given answers, not observation hardware or truth acquisition. Sole embedded mutation-named test uses literal Results.',
 'src/finite_trace.rs':'Complete322-line body covered by complete residual reading and exact renamed capacity blocks. Enumerates the entire connected component of a supplied executable word under state-relative certified adjacent swaps. ExactState additionally requires raw endpoint equality; ProtectedFutures uses behavioral equivalence, which preserves suffix availability by congruence. Canonical BFS discovery tree and sorted complete members are recomputed by replay; truncation is a typed refusal. This is a fixed-start, state-dependent word quotient, not a global trace monoid or arbitrary workflow permutation license. Limits count words/length/attempted swaps, not full time/bytes.',
 'src/context_reflection.rs':'Complete301-line body read. ContextSystem uses actual finite total action tables and profile equivalence. Private ContextHom checks complete endpoint structures, action commutation and relation preservation. CongruenceReflection repeatedly merges successor classes of currently related states, yielding the least stable equivalence above the initial relation; the identity-carrier unit and checked factorization establish the stated reflector in this chosen category. It can erase profile distinctions and is opposite in direction to report-preserving Moore refinement. A reflecting unit cannot repair noncongruence. Sole embedded mutation-named test uses literal Results.',
 'src/finite_functional_dependencies.rs':'Complete442-line body read. For1..8 attributes and at most128 supplied FDs, computes least attribute closure with derivation replay, all projected implications/BCNF violations, the FD-only binary lossless criterion, and lost dependencies. BudgetUnknown preserves incomplete-decision status; each tested dependency consumes work. Instance validation is separately bounded to128 distinct set tuples, and projection/natural join use exact equality with no NULL/bag semantics. Deserialized public reports are not validated certificates. Generic Ord/Eq/Clone laws are caller premises. Sole embedded mutation-named test uses literal Results.',
 'src/finite_functional_classification.rs':'Complete494-line body read; output-truncated line435 was separately recovered with lines431..442. Supplies constructive classifications of19 retention and20 functional signatures for explicitly defined finite-map predicates. Retention recognition factors through raw labels; observability is raw injectivity, reversibility is per-input permutation and minimality is Moore future separation. Functional stability means actual label invariance under the supplied context, not just kernel congruence. Constructors use at most4/3 states; universal implications plus witnesses establish completeness for these predicate classes, not a bound inferred from sampling. Implication routines enumerate Boolean signatures, including vacuous contradictory premises. No phenomenology follows; sole embedded mutation-named test uses literal Results.',
 'src/finite_retention_choices.rs':'Complete400-line body read. Counts and mixed-radix enumerates independently supplied total updates, readouts and arbitrary binary report comparisons using checked u128 arithmetic. Greatest-forward-relation iteration removes incompatible pairs to a finite greatest fixed point; it need not be an equivalence. Even an equivalence may fail to support literal report descent unless reports are constant on its classes. Zero report count gives zero packets without entering modulo-zero decoding. Counts are not an allocation budget. All256 two-state packet tests and nontransitive/universal tolerance counterexamples read, not run.',
 'src/finite_history_context.rs':'Complete417-line body read. Validated total subsequential word transducer includes initial, per-event and final emissions. Reachable product of original memory, transducer state and transformed memory represents all finite words, enabling exact state-descent or weaker profile-noncongruence decisions without a word cutoff. Replay recomputes; arbitrary HistoryContext implementations receive no such global guarantee. StateContextLift constructs representative histories exactly when the action preserves reachable states, without preserving the original chronology. Finite state-space proof does not impose operational resource limits. Sole embedded mutation-named test uses literal Results.',
 'src/finite_self_reference.rs':'Complete513-line body read. Private checked data validate finite carriers/maps and provenance-field ranges. Linkage verification means equality to declared accessible state/observer labels and membership in a supplied generation relation, not authenticated acquisition. Protocol evaluator_id is metadata; availability is supplied domain membership and success adds exact equality. Partial-report factorization includes None and differs from provenance availability. Successful report planning uses already supplied later targets and fabricates matching provenance records under those fixed tables; it is not prediction or independent truth discovery.19 aggregate signatures follow explicit implications and two-state constructors. Sole embedded mutation-named test uses literal Results; no consciousness inference.',
 'src/dagger.rs':'Complete254-line body read. DaggerStructure calls the canonical complete finite-category validator after explicit count bounds, then requires exact dagger-map domain, existing reversed-boundary images, involution, fixed identities and every reversed-composition equation. is_unitary checks both inverse equations. This is actual finite dagger-category admission, not a label census. Tests cover S3, a pair groupoid, all two-point relations and a refused walking-arrow assignment. Count bounds are not byte/time bounds and no Hilbert-space or physical interpretation follows. Rust tests read, not run.',
 'src/finite_groupoid.rs':'Complete266-line body read. FiniteGroupoid requires a validated dagger category and every arrow unitary. Deterministic connected components choose least roots/connectors; coordinates compute p_y^-1 g p_x in the root isotropy group with the documented first-then-second composition. The connected-thin criterion supports simplicity of a nonzero complex finite-groupoid algebra conditional on that separately chosen scalar algebra; it does not derive complex scalars, states or physical processes. Tests cover noninvertibility, C3, missing tables, empty groupoids and budget refusals. All tests read, not run.',
 'src/finite_joint_carrier.rs':'Complete161-line body read. Validates an explicitly supplied relation of pairs of local raw states: unique in-range rows and one answer per pair; local reports come from completed Moore quotients. It checks factorization through report pairs, constructs the joint answer refinement, and enumerates exact admitted fibers. Reverification recomputes results. Availability of local classes does not force an admitted joint pair. Checked arithmetic budgets counts only. No full Cartesian preparation, tensor product or physical interpretation is assumed. Sole embedded mutation-named test compares literal Results without exercising the owner.',
 'src/finite_continuation.rs':'Complete209-line body read. Strict nonempty rectangular partial dynamics with in-range successors is completed by a distinct absorbing unavailability sink, including a separate label from every usize report. Quotients delegate to Moore refinement and remove that last-indexed sink class for partial operations. run validates the entire word alphabet before execution. Pair-graph BFS yields a shortest distinguishing word when its explicit pair limit permits completion; exhaustion is refusal, not equivalence. Witness replay checks actual differing observations, not shortestness. Sink is mathematical unavailability, not a physical alternative. Sole embedded mutation-named test uses literal Results.',
 'src/finite_moore.rs':'Complete459-line body read. Implements exact finite deterministic Moore minimization: strict total table admission, report-kernel initialization, monotone refinement by successor classes, and exact fixed-point quotient. Certificate verification replays the entire canonical refinement chain and reconstruction, refusing arbitrary stable overrefinement. Surjective morphism factorization checks all reports/transitions; behavior-set comparison uses a disjoint-union quotient under shared external input/report meanings. Embedded tests include delayed distinctions, factoring, forged receipts and all216 three-state unary Boolean-output machines. No hard resource budget or semantic adequacy proof; Rust tests read, not run.',
 'src/finite_question_family.rs':'Complete383-line body read. Exact finite answer-profile quotient, strict table factorization, and partial-operation descent including availability constancy. Binary composition descent explicitly takes a full Cartesian source product; this is a declared domain assumption. Report-site construction keeps duplicate full-context rows to preserve possible gluing ambiguity, while proper contexts use unique projected profiles; restrictions are validated by FiniteReportPresheaf. Masks permit at most64 questions and a checked answer-cell count budget, not a CPU/byte guarantee. Empty carriers/families are supported. Sole embedded mutation-named test compares literal Results.',
 'src/finite_report_query.rs':'Complete448-line body read. Private total finite report/query maps are admitted with exact carrier/key coverage and no duplicate or extra rows. Decision constructs the unique decoder on the realized report image or an actual same-report/different-answer collision. Verification replays all equations or actual collision values. Refinement transfer checks common raw/query carriers and the whole commuting report triangle, then verifies the refined decoder. Uniqueness is restricted to the realized image; semantics of chosen carriers/report/query remain external. No explicit work budget. Sole embedded mutation-named test uses literal Results; no original execution.',
 'src/finite_report_descent.rs':'Complete571-line body read. Actual finite presheaf admission checks intersection-closed subset contexts, every total restriction, identities and all composition equations. Descent fibers check overlap compatibility and enumerate precisely the global extensions; cover classification separates uniqueness from existence and recomputes certificates. Two implementation gaps: constructor shifts a u64 before rejecting carrier sizes above64, and a zero final Cartesian product can pass a zero limit while an earlier prefix is materialized. These affect refusal/resource behavior, not the finite gluing criterion. All equality, ambiguity, refusal, empty-cover and budget tests read; no Rust execution.',
 'src/agent_functor.rs':'Complete149-line body read. FunctorTrait declares methods but no laws; AgentFunctor is an unrestricted descriptive record and does not implement that trait here. map_skill_morphism rewrites IDs/endpoints and replaces category/authority labels without validating the source category or supported skills; its representation does not preserve SkillMorphism composition IDs. MonotoneAgentImage separately checks relation preservation on listed source pairs, requiring valid indices, but does not prove either relation is a complete preorder or bind the numeric image to the label map. All tests read.',
 'src/bridges.rs':'Complete236-line body covered by residual reading plus exact renamed capacity blocks. StructurePreservingMap declares one map method with no laws. BridgeEvidence.preserve_law appends arbitrary text and is not checked evidence. ChargeBridge genuinely computes two checked i128 sums of i64 inputs and compares totals; it does not certify an actual map, other observables or semantics. Test DoubleMap is an illustrative integer function, with ordinary overflow behavior outside shown values. All tests covered.',
 'src/density_matrix_functor.rs':'Complete79-line body read. DensityMatrixFunctorWitness stores an arbitrary float and label without validation or matrices. RankOneRationalWeight correctly reduces a rational in(0,1] and its complement, including0/1 defect at weight1. This is scalar arithmetic only; identifying it as density trace requires a separately supplied normalized rank-one projector, absent here. Numerical-profile comment does not describe the exact integer witness. All tests read.',
 'src/morphism.rs':'Complete175-line body read. SkillMorphism is public descriptive metadata, not a state-transition function. Legacy compose checks endpoint labels only, contrary to its category-matching comment; try_compose adds the missing category check. try_associate checks concatenated IDs and boundary/category fields but omits description, which differs under the derived full PartialEq for the two bracketings. No identity constructor/law or execution semantics is supplied. Source authority/ceiling are copied without combination. All tests read.',
 'src/mssn_functor_bridge.rs':'Complete138-line body read. Bridge constructor labels an adjunction and supplies a lift/forget evidence string without a map. TriangleWitness checks total endomaps on a chain of1..16 points, both triangle equations and unit/counit inequalities, but never monotonicity. The order-reversing two-point swap used for both maps passes all predicates yet is not a chain functor or Galois connection. All tests read.',
 'src/zeta_functor.rs':'Complete163-line body read. Float/primitive-orbit record is unvalidated and not functorial. ExactEulerProduct validates distinct u32 primes by trial division, forms product p/(p-1) in checked u128 arithmetic and reduces by GCD; empty list yields1/1. Conservative unreduced intermediate overflow can refuse a representable reduced result. No orbit-to-prime map, infinite-product convergence or category laws are supplied. All tests read.',
 'src/hott_topos_bridge.rs':'Complete100-line body read. HoTT interpretation record checks only three nonempty trimmed labels and ignores evidence strings. try_kripke_implication substantively checks persistence of two Boolean atom valuations along a finite chain and whether every world satisfies not-a or b, the correct implication condition at the least world for nonempty chains. It returns true for an empty chain although advertised world0 does not exist. No general formula semantics, HoTT judgments or topos model. All tests read.',
 'src/simplicial_hott_bridge.rs':'Complete108-line body read. SimplicialPathWitness coherence means vector length only. InnerHornWitness checks two nonempty labels,dimension>=2,strictly interior missing-face index and coherence-cell count+1=dimension. It has no face/degeneracy maps, compatible horn boundary or filler/path equality; this is index/count metadata, not a simplicial or HoTT witness. Sole mutation-named test compares literal Ok and Err without calling the owner. All tests read.',
 'src/topos_hott_model.rs':'Complete98-line body read. Minimal-model validation only requires nonempty universe/identity-label vectors, allowing empty labels. ToposUniverseWitness adds nonempty model name, equal counts and at-most-universe truncation count; no model interpretation, type rules, universe inclusion or truncation equations. Count equality is not a HoTT/to-pos semantic model. All tests read.',
 'src/category_contract_alignment.rs':'Complete178-line body read. Ten fixed rows associate concept names with URNs, strata labels and active flags. binding_lattice_holds checks URN uniqueness, allowed strata and exactly ten active rows. No order relation, meet or join is defined, so lattice is only this registry consistency label and not a mathematical lattice certificate. Contract strings do not validate corresponding Rust implementations. All tests read.',
 'src/arrow.rs':'Complete244-line body covered by complete residual reading and exact renamed repeated tests. Actual higher-order combinators thread read-only context, state, writer and Result through typed closures. compose and split are sequential; fanout clones only the input and threads first-branch state into the second, so branches are not isolated or parallel. Errors discard accumulated writer/state because Result encloses the tuple. Extensional laws need suitable pure/deterministic closure premises; Send+Sync does not forbid external effects. Capacity witness is separate from these semantics. No dedicated combinator test occurs in this body.',
 'src/bounded_counter.rs':'Complete125-line body read. CounterReport stores remaining depth r and clipped nonnegative count min(n,r); advance decreases depth and implements increment/decrement legality without overflow. observe preserves the first guard refusal even with a longer unexecuted suffix. Distinct clips at equal depth are separated by min(clip1,clip2)+1 decrements, within depth; equal clips have equal guarded futures by the transition invariant. This is a useful finite-depth quotient and not a fixed-depth congruence for unlimited futures, as explicitly documented. Sole embedded mutation-named test exercises literal Result values, so independent finite counter controls are recorded separately.',
 'src/mod.rs.legacy':'Complete165-line body read. Historical compatibility module contains category/functor/monoidal traits, string witnesses, law-check interfaces and reexports. None of those traits enforces categorical equations. Legacy filename is not an active Rust module declaration by itself; current lib.rs is the separately reviewed owning module map. Mentioned dependencies receive no reading credit through these declarations. No embedded executable tests.',
 'src/category/mod.rs':'Complete112-line body read. Reexports are shells. IntegerFiniteCategoryWitness checks nonempty ordinal objects, arrow endpoints in range and at least one loop at each object; it neither designates identities nor supplies composition. The reflexive graph on0,1,2 with0->1 and1->2 but no0->2 passes yet cannot be a category on those arrows. The sole mutation-named test only compares hand-constructed Ok/Err values, not this witness. Historical mutation count remains unverified.',
 'src/category/category.rs':'Complete248-line body read. FiniteCategoryShell validation checks nonempty labels only, not uniqueness, membership or laws. Its separate certify_identities checks unique nonempty objects, exact identity-map key coverage and existence of each designated same-object arrow. It does not enforce unique morphism names, nonidentity endpoint membership or any identity/composition equation; DuplicateMorphism is unused here. This is useful designated-loop census, not category admission. All tests read.',
 'src/category/small_category.rs':'Complete240-line body covered by residual reading plus exact renamed capacity blocks. Shell requires a smallness Boolean and presentation label checks; it contains finite data but no category-law certificate. certify_presentation adds unique nonempty morphism names to the designated-loop census, without verifying general arrow endpoints or composition. Empty presentation-label comment is not realized because underlying validation rejects it first. All tests covered.',
 'src/category/discrete_category.rs':'Complete210-line body read. Initial shell confuses same endpoints with identity and lacks coverage. Separate DiscreteIdentityWitness checks unique nonempty object labels and exactly one loop occurrence per object, refusing unknown endpoints and nonloops. That graph admits the unique discrete-category composition when arrow occurrences are treated as elements. Arrow names may be empty or repeated across objects, because admit does not call shell validation or enforce global-name identity. Empty discrete category is accepted. All tests read.',
 'src/category/terminal_category.rs':'Complete153-line body read. Shell stores one object and one identity label. TerminalWitness only admits identity names id or id_<object>, then assigns counts1,1 and checks1*1=1. The singleton structure has a unique possible category law, but no explicit table or universal functor is stored; the name restriction rejects an equivalent singleton presentation with identity e. All tests read, including a name-only negative case.',
 'src/category/opposite.rs':'Complete254-line body covered by residual reading plus exact renamed capacity blocks. reverse_of actually swaps arrow endpoints. OppositeCensus checks in-range ordinal boundaries and the tautological double swap, then retains only counts. It has no identities/compositions or complete opposite-category construction; the finite reversal is valid on any graph including empty graphs. All tests covered.',
 'src/category/product_category.rs':'Complete174-line body read. ProductCardinality checks named shell, supplied left*right count equals pair-tag vector length, and each tag has exactly two nonempty pipe-separated components. It checks neither unique pairs nor coordinate membership/coverage. Four identical a|x tags pass as a2x2 product inventory. Thus arithmetic/encoding validity does not establish the claimed Cartesian inventory; actual product arrows and universal maps are absent. All tests read.',
 'src/category/sum_category.rs':'Complete158-line body read. Diagnostic label/object arrays are separate from DisjointSum, which checks duplicate-free u32 IDs within each side and returns checked sum of lengths; the same raw ID across sides is correctly counted twice under conceptual tagging. It stores no tags/elements or arrow laws and does not bind numeric inputs to shell inventories. All tests read.',
 'src/category/arrow_category.rs':'Complete164-line body read. ArrowCategoryShell lists arrow-object labels only. FunctionSquare is a substantive bounded check of four total endomaps on1..12 points: every point satisfies right(top(i))=bottom(left(i)). This is an actual commuting-square predicate for supplied finite functions, not a construction of the entire arrow category or a connection to named base arrows. All tests read.',
 'src/category/slice_category.rs':'Complete206-line body read. SliceTriangle checks an endomap on1..12 points, a fixed apex,1..12 selected source occurrences mapping to that apex, and listed mediator pairs whose target equals step(source). Since all selected sources map to the apex, every admitted mediator targets an apex occurrence. This narrow one-step graph predicate is not the full slice category; even the identity mediator on a non-apex leg is refused by design. Duplicate leg sources and empty mediator list are allowed. All tests read.',
 'src/category/coslice_category.rs':'Complete153-line body read. OutgoingCount checks each supplied arrow starts at tip and all targets are distinct, then returns their count. This is a restricted outgoing-star inventory, not one fixed hom-set or arbitrary coslice object count: legitimate parallel arrows become separate coslice objects but are refused by the unique-target rule. No target carrier, identities or triangles are supplied. All tests read.',
 'src/category/discrete_fibration.rs':'Complete147-line body read. Object-map shell has no functor action or lift data. FiberCensus only checks positive declared total equals the checked sum of supplied fiber sizes; it does not derive a partition from the object map. Discrete fibers imply discrete fibration only with the missing fibration/lift premise, not for an arbitrary functor. Empty total is an explicit narrower contract. All tests read.',
 'src/category/fibered_category.rs':'Complete213-line body read. DiscreteCleavageWitness checks in-range total graph endpoints and exactly one source-fiber-matching edge into every target above each listed base endpoint pair, requiring at least one hit. Base arrow identities and projection of total arrows are absent, so parallel base arrows are conflated; duplicated base boundary pairs can reuse the same edge. No base/total category laws, functor projection, identity coverage or cartesianness are established. All tests read; positive fixture itself omits category identities.',
 'src/category/opfibration.rs':'Complete137-line body read. Shell checks labels and leaves cloven flag as a declaration. CleavageWitness tests chosen_lifts=base_morphisms when cloven, else chosen_lifts=0, and counts supplied cofiber labels. It neither enumerates a lift for each base-arrow/source-object pair nor checks cocartesianness or any functor; interpreted as individual lifts, the count misses fiber multiplicities. All tests read.',
 'src/enriched/mod.rs':'Complete157-line body read. HomSquare validates nonempty unique object labels (at most16), exactly n^2 hom-object entries, known endpoint objects and each ordered pair exactly once. This is useful total-table/coverage validation, with nonempty hom labels supplied by the shell. It supplies neither base-category membership nor enriched composition/unit maps and laws. All tests read.',
 'src/enriched/base_category.rs':'Complete161-line body read. Base category is a label/monoidal-ref shell. BaseEnrichmentWitness checks positive supplied object count, its square, consistency of a nonempty closed_ref with presence of the hom-count, and equality to n^2. This counts pair-indexed hom assignments, not necessarily distinct hom objects; repeated internal hom objects are normal. It does not locate a unit or prove closedness. Even nonclosed cases compute the unused square and may overflow. All tests read.',
 'src/enriched/enriched_category.rs':'Complete216-line body read. Initial shell allows unbound or missing composition/identity references and does not validate hom coverage. Separate UltrametricHomWitness checks a finite square nonnegative-integer matrix for zero diagonal, symmetry and every strong-triangle inequality; computes diameter. It allows distinct indices at zero distance, so the exact carrier is a pseudoultrametric. Numeric indices/size are not tied to shell objects or hom labels, and no order convention/base coherence is validated. All tests read.',
 'src/enriched/enriched_functor.rs':'Complete156-line body read. EnrichedFunctor shell leaves object/hom map refs unchecked. EnrichedCompositionDimWitness requires all positive counts and dim_ac=dim_ab*dim_bc, with checked multiplication. This gives a tensor-product dimension, but enriched composition is generally a morphism from that tensor product, not an isomorphism onto the hom-object. A one-object category from the2-dimensional algebra F2 x F2 has lawful composition with dimensions4->2 and is rejected. Only shell tests occur.',
 'src/enriched/enriched_natural_transformation.rs':'Complete131-line body read. Transformation shell omits component-reference checks and actual maps. NaturalitySquareWitness multiplies positive component count by4; it does not enumerate enriched naturality diagrams or verify a commuting equation. Counts and literal2*2 cannot certify naturality. All tests read.',
 'src/enriched/enriched_adjunction.rs':'Complete139-line body read. Adjunction shell checks four labels and omits hom-isomorphism reference. HomIsoRanks only tests equality of two u64 counts, including zero. A supplied rank equality is at most necessary in an appropriate linear interpretation and neither proves a particular hom-map invertible nor its naturality; no categories or functors are computed. All tests read.',
 'src/enriched/enriched_presheaf.rs':'Complete234-line body covered by all residual lines plus exact renamed capacity blocks. Presheaf shell leaves object assignment and action refs unchecked. HomDimensionSum adds a nonempty list of positive supplied dimensions, with overflow/count guards. It excludes empty/zero-dimensional cases by an explicit restricted contract and supplies no enriched functor action or laws. All tests covered.',
 'src/enriched/weighted_limit.rs':'Complete155-line body read. WeightedLimit shell does not require apex. FiniteWeightedLimitCard correctly computes checked-u64 finite function-space count D^W, including0^0=1 and special zero/one bases. For base>=2, exponents>63 cannot fit u64 and are refused. Interpreting this as a weighted limit requires a discrete single-object index; nontrivial one-object monoid actions introduce equivariance constraints not represented here. All tests read.',
 'src/enriched/weighted_colimit.rs':'Complete174-line body read. Label shell separate from DiscreteWeightSum, which computes sum(weight_i*diagram_i) on1..16 equal-length u32 lists with u128 arithmetic. It is accurately described as a discrete weighted-colimit cardinality conditional on the supplied finite-set/discrete model, without constructing coproduct elements, functor actions or a general coend. All tests read.',
 'src/abelian/mod.rs':'Complete113-line body read. Exports explicitly separate shells from core_homology. ShortExactRankWitness constructs the standard split coordinate ranks a,a+c,c and checks disjoint inclusion/projection coordinate blocks. Its claim is accurately restricted to that free-abelian split model; it refuses the all-zero case and nested loops have no small resource cap beyond u32 arithmetic. No generic exactness test. Both tests read.',
 'src/abelian/abelian_category.rs':'Complete207-line body read. Label/Boolean shell explicitly omits normal-mono/coimage-image obligations; additive plus kernels/cokernels alone are preabelian conditions, despite abbreviated abelian-checklist wording. RankNullity separately checks rank+kernel=source and rank+cokernel=target on supplied counts; no linear map, coefficient ring, torsion, rank computation or abelian-category law is supplied. All tests read.',
 'src/abelian/additivity.rs':'Complete213-line body read. Additivity flags are diagnostic only. IntegerBiproduct concretely builds basis-coordinate inclusions/projections for free abelian groups of positive ranks<=8; the public identities checker validates table lengths and all four projection-inclusion equations. These force disjoint injective images covering the summed-rank basis, hence the complementary sum identity under the declared linear extension. Useful finite free-module biproduct model, independent of category labels. All tests read.',
 'src/abelian/exact_category.rs':'Complete165-line body read. ExactCategory label/optionalpositivecount shell disclaims Quillen axioms. ShortExactWitness only requires supplied counts3objects/2maps; it checks neither composition nor kernel/image exactness. Its nonzero_objects terminology is too restrictive for short exact sequences having a zero interior object, and counts are not an exactness certificate. All tests read.',
 'src/abelian/chain_complex_category.rs':'Complete191-line body read. ChainComplexCategory stores degree labels/bounds only. degree_span subtracts ordered i32 bounds before casting to u32, permitting arithmetic overflow despite valid ordering; default debug behavior panics. ChainRankCertificate computes dimensions minus adjacent supplied ranks, verifies nonnegativity and Euler cancellation. It needs independently checked differentials with d squared zero and actual ranks; same counts can come from noncomplex maps. No torsion or chain-category construction. All tests read.',
 'src/abelian/derived_category.rs':'Complete155-line body read. DerivedCategory is a base-name shell without quasi-isomorphism localization. ShiftEuler computes alternating rank sum for at most32 u32 entries and negates twice, correctly modeling rank Euler signs under shifts. No differential, localization, actual shifted complex or derived equivalence is constructed; empty list is allowed. All tests read.',
 'src/abelian/homological_algebra.rs':'Complete133-line body read. Umbrella homological vocabulary is a label shell; base label may be empty and no homology crate is linked here. ShortExactRanks checks only supplied left+right=middle, including zero, with overflow refusal. This is a necessary dimension relation for finite-vector-space short exact sequences, not a test of maps, exactness, Ext, Tor or spectral sequences. All tests read.',
 'src/limits_colimits/pullback.rs':'Complete212-line body read. Pullback shell has only reference labels. PullbackPairWitness accepts two nonempty finite relation lists with each domain key occurring exactly once, then counts pairs of map values agreeing at the integer-labeled apex. This is a genuine finite-set pullback cardinality on the supplied domains; even duplicate identical key/value rows are refused by its unique-key encoding rule. No independent named carrier membership or mediator is stored. All tests read.',
 'src/limits_colimits/pushout.rs':'Complete196-line body read. Reference-only span/pushout shell. MonicPushoutWitness checks supplied apex count<=both target counts and the inclusion-exclusion formula left+right-apex with conservative intermediate overflow refusal. It contains no actual injections or quotient relation, so the count equality requires independently admitted monic finite-set legs. Only shell tests occur here.',
 'src/limits_colimits/kernel_pair.rs':'Complete211-line body read. KernelPair shell has no executable relation. KernelPairCount genuinely validates a total ordinal endomap on1..16 points, computes every fiber size and sum of squares, and cross-checks against complete enumeration of ordered equal-image pairs. It stores the number, not the kernel equivalence relation. All tests read.',
 'src/limits_colimits/cokernel_pair.rs':'Complete166-line body read. Shape shell separate from FiniteCokernelCardinality. The latter computes2*target-source with source<=target and checked arithmetic, an accurate conditional finite-set pushout count for an injective map. Count inequality does not prove a given map is injective; no map is supplied. Conservative intermediate overflow may refuse a representable final count. All tests read.',
 'src/limits_colimits/end.rs':'Complete162-line body read. End shell holds only category/bifunctor/object labels. EndDiagonalWitness computes checked product of a nonempty list of positive counts and tests supplied end_size<=product. This is a necessary finite-set bound under an admitted end construction, not an end or its compatibility constraints; zero and empty diagonal cases are deliberately excluded. Only shell tests read.',
 'src/limits_colimits/coend.rs':'Complete180-line body read. Coend shell separate from DiscreteCoend, which sums supplied nonempty diagonal sizes in both orders and checks claimed sum. This is the correct cardinality formula conditional on a discrete index category and finite-set values, but no category discreteness or bifunctor maps are checked. General coend identifications are absent. All tests read.',
 'src/limits_colimits/kan_extension.rs':'Complete237-line body read. Lan/Ran shells validate labels, ignoring unit/counit reference. PointwiseKan sums or multiplies supplied fiber sizes, including correct empty sum0/product1, and compares a claimed value. These formulas apply to finite-set (co)limits over discrete comma diagrams; the API supplies neither diagrams nor discreteness nor transition maps, so it does not compute general pointwise Kan extensions. All tests read.',
 'src/limits_colimits/pointwise_kan_extension.rs':'Complete195-line body read. Shape-only F/K/extension/formula labels. PointwiseCensus checks equality of two supplied counts, including0, and records Lan/Ran tag. Equal counts do not prove that each object received one computation or that any (co)limit exists; no object-indexed results or universal properties occur. All tests read.',
 'src/limits_colimits/density_comonad.rs':'Complete212-line body read. DensityComonad label shell is distinct from DensityCommaWitness. The latter checks a complete relation on1..8 objects for reflexivity/transitivity, deduplicates pairs, then counts subcategory elements below every target. This concretely counts objects of inclusion-comma categories in the admitted preorder, but constructs neither their colimits, density/comonad structure nor laws. All tests read.',
 'src/limits_colimits/mod.rs':'Complete106-line body read. Hierarchy exports are explicitly shells distinct from flat computational owners. PullbackCount actually enumerates all pairs of positions in two supplied u32 image lists and counts equal images, with checked cardinal conversions/product bound. This computes a finite-set fiber-product cardinality on the implicit common integer-label codomain; it retains count only and does not construct universal mediators. Test read.',
 'src/limits_colimits/limit.rs':'Complete141-line body read. Limit validates nonempty diagram reference and Cone shell, without concrete diagram or universal property. Independent FiniteProductCardinality performs checked-u64 multiplication and redundant nonzero-factor division identity, accepting zero factors. Product arithmetic is not bound to the labeled limit. All tests read.',
 'src/limits_colimits/colimit.rs':'Complete174-line body read. Colimit reference/cocone shell has no universal property. CoproductIndex concretely encodes/decodes tagged ordinal sums with range/overflow guards, but constructor always probes first right-summand element. Therefore any empty right summand is refused even when a valid finite sum exists. Positive2+3 example is the sole index test. All bodies read.',
 'src/limits_colimits/cone.rs':'Complete232-line body read. Cone and Cocone hold apex/nadir and string leg pairs. Shells validate nonempty tags only; additional ConeLegWitness enforces uniqueness of diagram indices and count conversion. No diagram-object coverage, morphism boundaries, commuting equations or universal mediator. Empty leg families are allowed, appropriately including possible empty diagrams but without a bound diagram. All tests read.',
 'src/limits_colimits/product.rs':'Complete170-line body read. Product shell requires nonempty factor labels, permits absent projection vector and otherwise checks count alignment. ProductCardinalities computes checked product and returns constant projection_count2; actual projections or unique pairing are not supplied despite witnessed-by-projections wording. Count predicate remains useful finite cardinal arithmetic, not categorical evidence. All tests read.',
 'src/limits_colimits/coproduct.rs':'Complete178-line body read. Coproduct shell permits absent injections; supplied injection count must match summands. CoproductCardinalities computes checked sum and constant injection_count2, without injection maps or universal copairing. This arithmetic owner accepts zero summands, unlike the separate CoproductIndex constructor defect. All tests read.',
 'src/limits_colimits/equalizer.rs':'Complete147-line body read. Equalizer shell checks reference strings only. EqualizerDimensionWitness enforces positive supplied dimensions and equalizer<=source, then returns constant parallel_arrows2. It excludes valid zero-dimensional/empty equalizers and supplies no parallel maps, equality or universal factorization; strict domain is a narrower count envelope. All tests read.',
 'src/limits_colimits/coequalizer.rs':'Complete231-line body read. Shell separate from substantive EndoCoequalizer: two total in-range endofunction arrays on1..16 points; union-find merges each image pair and counts equivalence classes. Parent forest merges roots and bounded path compression preserve termination in this finite carrier. This is the finite-set coequalizer class count, not a constructed quotient map or arbitrary-category universal property. Positive cycle and out-of-range tests read.',
 'src/limits_colimits/terminal_object.rs':'Complete117-line body read. TerminalObject is explicitly diagnostic. TerminalArrowWitness validates labels and positive object count, then assigns arrows_into_terminal=object_count without inspecting any hom-set. It is the expected number conditional on terminality, not a terminal-object certificate. All tests read.',
 'src/monoidal/braided_monoidal.rs':'Complete117-line body read. BraidedMonoidal is a nonempty-reference shell. BraidPresentationWitness takes object_count>=2, reports generators=count-1 and fixed relation_length3/both_sides6; no braid words, relations, natural isomorphisms or hexagon equations are supplied. Integer count consistency only. Embedded tests read; mutation-accounting comment is a retained assertion, not a fresh receipt.',
 'src/monoidal/symmetric_monoidal.rs':'Complete145-line body read. symmetric_claimed is explicitly diagnostic and ignored by shell validation. BraidingDimensionWitness separately requires positive dimensions and both supplied tensor dimensions equal their checked product. It certifies dimensional equality, not a braiding, symmetry equation or naturality. Only shell tests occur in this body; no native run.',
 'src/monoidal/symmetric_monoidal_functor.rs':'Complete128-line body read. Shape validation omits even the braiding-preservation reference, and the shell does not contain actual maps. SymmetryOrderWitness checks a supplied positive even application count and halves it. Evenness alone does not establish symmetry or functor preservation; this is arithmetic metadata. All tests read.',
 'src/monoidal/cartesian_closed.rs':'Complete245-line body covered by all residual lines and exact renamed capacity-block comparison. CCC shell requires nonempty references only. ExponentialCard computes checked-u64 powers for exponent<=16, explicitly excluding0^0. Useful bounded arithmetic, but that exclusion omits the singleton set of functions from empty set to empty set, and no evaluation/currying maps or universal property are constructed. All tests covered.',
 'src/monoidal/closed_monoidal.rs':'Complete203-line body read. ClosedMonoidal shell checks internal-hom reference but not optional evaluation. InternalHomDimension compares two supplied nonempty equal-length count vectors pointwise and computes checked totals. It neither derives counts nor supplies a natural hom-set bijection or closed structure; final total comparison is redundant after exact row equality. All tests read.',
 'src/monoidal/compact_closed.rs':'Complete159-line body read. Shape-only dual/cup/cap references. SnakeDualDimension requires a positive supplied dimension, equal dual dimension and cup-codomain count=dimension squared with overflow guard. No actual cup/cap coefficients or snake contraction is checked. This is a dimension predicate appropriate to the stated finite-dimensional interpretation, not a compact-closed certificate. All tests read.',
 'src/monoidal/rigid_category.rs':'Complete196-line body read. Reference shell omits checking unit/counit strings. Separate SnakeIdentityWitness genuinely checks every entry of a supplied square integer counit matrix against contraction with a fixed standard coevaluation, on ranks1..6, with checked arithmetic. Because the fixed coevaluation is the identity matrix, acceptance is exactly counit=identity. Useful finite standard-dual check; no arbitrary dual assignment or complete monoidal coherence. All tests read.',
 'src/monoidal/traced_monoidal.rs':'Complete223-line body covered by all residual lines plus exact renamed capacity blocks. Trace operator exists only as a label. TraceCard checks nonzero trace-object count and checked products for source/target tensor dimensions, allowing zero source/target. No trace of a morphism or trace axioms are evaluated. All shell/arithmetic/capacity tests covered.',
 'src/monoidal/cohomology_in_monoidal.rs':'Complete206-line body read. Diagnostic monoidal-cohomology shell separate from GroupCocycle. For group Z/n,n=1..6, GroupCocycle checks all triples using the trivial-action2-coboundary formula but tests residue modulo n rather than integer zero. It does not enforce normalization at identity arguments. Thus it is an unnormalized Z/n-coefficient cocycle check on integer representatives, with overflow refusal, despite its normalized-integer comment. Explicit normalized n3 table passes residues while integer coboundary reaches +/-3. Tests read, no original Rust execution.',
 'src/monoidal/mod.rs':'Complete85-line body read. Exports11 diagnostic hierarchy modules. TensorDim::try_associate checks checked-u32 equality of(ab)c and a(bc) on three supplied dimensions, rejecting intermediate overflow. This is integer associativity, with no associator maps or coherence diagrams. The3*5*7=105 test was read, not executed.',
 'src/monoidal/monoidal_category.rs':'Complete181-line body read. Shell validates nonempty underlying/tensor/unit/associator/unitor labels without structures or laws. MonoidalCoherenceCensus separately accepts positive object count and computes checked n^3 associator component indices and2n unitors. This is a count of possible indices, not actual natural maps or pentagon/triangle coherence. Both positive and zero-refusal tests read.',
 'src/monoidal/monoidal_functor.rs':'Complete159-line body read. Shell validates label/domain/codomain/functor refs only; optional strength/tensorator/unit-comparison strings and strong_claimed flag are not checked. StrictTensorDimension separately computes checked-u64 multiplication including zero dimensions, independent of any functor or strictness proof. Product and overflow tests read; no native execution.',
 'src/monad/mod.rs':'Complete144-line body read. Shell catalog reexports differ from computational legacy monads. MonadKleisliCensus validates labels/equal supplied hom counts, positive object count and identities<=homs, but additionally rejects unit_ref=multiply_ref. That distinction is not a monad axiom and rejects a legitimate identity monad representation. Counts do not locate identities in a particular hom-set. Its test explicitly enshrines the name inequality. No native execution.',
 'src/monad/monad.rs':'Complete196-line body read. Labeled Monad shell expressly leaves laws external. CyclicWriterWitness concretely checks addition modulo n for n=1..12: right unit and every associativity triple; commutativity of the fixed addition also supplies left unit mathematically, but no writer type/functor/transformations are built or bound to shell refs. Both tests read.',
 'src/monad/comonad.rs':'Complete196-line body read. Reference shell separate from ProductComonadLaw. The latter encodes pairs as mixed-radix integers for positive carrier/context<=8 and checks both counit restorations after duplication on every pair. It does not separately check coassociativity or bind a generic comonad to the labels; the fixed product construction is the scoped model. All tests read.',
 'src/monad/algebra_for_monad.rs':'Complete237-line body covered by residual reading and exact renamed capacity-block comparison. Shell only carrier/action/monad labels. AlgebraCard checks carrier<=free_carrier and image<=carrier, not unit retraction or associativity; actual algebra unit retraction would force the action image to equal the carrier. Smaller images pass this necessary-count envelope. Tests read.',
 'src/monad/coalgebra_for_comonad.rs':'Complete207-line body read. Shell-only labeled coalgebra. CoalgebraLaws checks four nonempty common-size ordinal arrays, epsilon(structure(x))=x and comultiply(structure(x))=extended(structure(x)). This is an exact finite section/equality test; extended is supplied freely, not computed as W(structure), and no comonad laws/action or varied carrier types are represented. Retraction on equal finite sizes forces a bijection, narrowing the model. All tests read.',
 'src/monad/distributive_law.rs':'Complete147-line body read. DistributiveLaw is a labeled transformation shell. Separate FiniteDistributiveCardinality verifies checked integer factor*(left+right)=factor*left+factor*right, including conservative intermediate overflow refusal. This is cardinal arithmetic, not a monad distributive law or its unit/multiplication diagrams. Tests read.',
 'src/monad/eilenberg_moore.rs':'Complete186-line body read. EM category reference shell separate from FiniteMonoid. FiniteMonoid genuinely validates a complete flattened multiplication table of order1..8: exact size, closure, fixed zero two-sided unit and every associativity triple. It stores order only, not the table; no EM-algebra category is constructed. All tests read.',
 'src/monad/kleisli_category.rs':'Complete141-line body read. Explicitly shape-only shell refers readers to root computational owners. KleisliHomWitness verifies equality of two supplied u32 counts, including zero; no base/Kleisli hom-set data or correspondence is built. All tests read.',
 'src/monad/monad_transformer.rs':'Complete145-line body read. MonadTransformer is a label/ref shell without lift or law validation. StateCardinalityWitness multiplies two positive u64 counts with overflow checks. Its StateT cardinality comment describes A x S rather than total state computations S->A x S in the identity-base finite-set model; with |A|=|S|=2 these are4 and16 respectively. Official transformers documentation confirms the function-space definition. All shell tests read; no transformer implementation or native run.',
 'src/adjunction/mod.rs':'Complete132-line body read. Explicit shell catalog/legacy reexports. GaloisWitness genuinely validates nonempty chains of independently sized <=8 elements, total in-range monotone lower/upper arrays and the adjunction biconditional on every pair. This is a concrete finite order adjunction, independent of labeled diagnostic shells. Both tests read.',
 'src/adjunction/adjunction.rs':'Complete178-line body read. AdjunctionShell checks nonempty functor/unit/counit labels and explicitly disclaims triangle proof. AdjunctionHomWitness adds positive equal supplied hom-counts and computes triangle_steps=2*2; it does not evaluate triangles or construct a natural hom-bijection. Zero-hom adjunction instances are outside that narrower count contract. Tests read.',
 'src/adjunction/hom_set_adjunction.rs':'Complete217-line body read. Diagnostic mate pairs include object/morphism tags. certify_mate_bijection checks a nonempty list with distinct nonempty left and right tags, giving a bijection between the listed tag sets only; it ignores object contexts, full hom-set coverage, functor labels, shell validity and naturality. Source explicitly limits the shell. All tests read.',
 'src/adjunction/galois_connection.rs':'Complete245-line body read. Initial pair-list shell does not certify totality/monotonicity. Separate FiniteGalois genuinely checks same-sized nonempty chains<=8, full in-range monotone maps and every adjunction biconditional. It overlaps the unequal-size module-level GaloisWitness without linking either to shell tags. All tests read.',
 'src/adjunction/adjoint_functor_theorem.rs':'Complete198-line body read. Hypotheses, direction and solution-set are diagnostic strings; direction is merely nonempty. SolutionSetCoverWitness checks positive supplied solution count<=comma count and supplied covered=comma count, not a cover map, weakly initial family, completeness or adjoint existence. It appropriately does not implement the general theorem. All shell tests read.',
 'src/adjunction/unit.rs':'Complete184-line body read. UnitShell keeps a string-keyed component map and validates nonempty tags only, allowing an empty family. UnitComponentCount separately checks positive objects=components with no link to the shell map, coverage, boundaries or naturality. All tests read.',
 'src/adjunction/counit.rs':'Complete232-line body read. CounitShell is explicitly shape-only. TriangleIdentity checks two nonempty equal-sized ordinal arrays are mutual inverse functions, including both roundtrips/ranges; it does not apply left/right functors or bind to shell components. This is a useful bijection predicate rather than a general adjunction triangle certificate. All tests read.',
 'src/adjunction/reflective_subcategory.rs':'Complete207-line body read. Labels for ambient/subcategory/reflector, optional unchecked inclusion/unit/counit refs. ReflectiveCensus validates supplied sub_objects<=ambient_objects and checked difference, including zero counts, with no actual inclusion or adjunction. All tests read.',
 'src/adjunction/coreflective_subcategory.rs':'Complete276-line body covered by all residual lines plus verified identifier-renamed capacity blocks. Shell is explicitly diagnostic. CoreflectorCount checks subcategory<=ambient and sets counits=subcategory. A counit i*c=>Id_C has a component at each ambient object; the chain0<1 coreflecting onto{0} has two, while the counter returns one. Restricted-subcategory counting would be a different, narrower interpretation. Tests explicitly expect subcategory count. No native execution.',
 'src/functor/equivalence_of_categories.rs':'Complete278-line body covered: all residual lines read and repeated capacity blocks verified by exact identifier renaming against the fully read baseline. Equivalence shell requires two functor labels, with optional unchecked unit/counit refs. Separate FiniteBijection checks both inverse equations pointwise on equal-length finite ordinal arrays with range/overflow guards, including empty arrays. This is a finite set bijection, not functor laws or categorical equivalence. All embedded tests covered.',
 'src/functor/isomorphism_of_categories.rs':'Complete191-line body read. Shape-only inverse-functor references. MutualInverse separately checks nonempty equal-length u16 arrays are in-range mutual inverses at every index; establishes a finite ordinal bijection, without object/arrow maps, identities or composition. All tests read.',
 'src/functor/free_functor.rs':'Complete151-line body read. Shape-only free-functor labels. FreeWord constructs two concatenations of the three supplied u32 words, compares every element and checked-sums their lengths; concrete free-word associativity instance, not a general free-group/universal-property construction. Allocation occurs before checked length conversion, so integer overflow refusal is not a resource bound. Test read.',
 'src/functor/presheaf.rs':'Complete148-line body read. Presheaf shell is only label/category ref. Restriction witness checks equal-length integer count arrays, image<=domain and total differences; no restriction maps, functor equations or presheaf are supplied. The inequality is appropriate for cardinality of an actual image, not necessarily the entire target section set, which may be larger than the source. Empty count arrays permitted. Tests read.',
 'src/functor/copresheaf.rs':'Complete129-line body read. Shape-only copresheaf reference. SectionCardinalWitness checked-sums a nonempty u64 count list and records list length; no sets, transition maps, overlap/canonical colimit or functor laws. Zero individual counts allowed. Shell tests read.',
 'src/functor/functor_category.rs':'Complete200-line body read. Category reference shell does not construct a functor category. NaturalitySquareWitness checks three equal-size nonempty bounded ordinal maps and every equation alpha(source(x))=target(alpha(x)); a useful complete finite intertwining-square check, but no complete categories/functor population or all arrows are supplied. Both examples read.',
 'src/functor/representable_functor.rs':'Complete208-line body read. Representing-object label is optional in the explicitly shape-only shell. RepresentableHom separately checks count-vector length, nonempty object count, chosen index and positive diagonal count; no hom-map action or natural isomorphism establishes representability. Tests only count/index conditions. No execution.',
 'src/functor/yoneda.rs':'Complete150-line body read. Yoneda is a labeled shell. YonedaRowSumWitness checks square nonempty u64 table, positive diagonal entries and overflow-safe row sums. It supplies neither a composition law, a valid category hom-table, Yoneda embedding nor natural-bijection proof. A three-object table with arrows A->B and B->C but zero A->C passes these numeric guards despite impossible categorical composition. Source has no tests for this appended row-sum owner; only shell tests.',
 'src/functor/mod.rs':'Complete196-line body read. Reexports explicitly qualified diagnostic shells. HomPartition validates a bounded directed multigraph endpoint census (1..16 objects, <=64 arrows) and equality of total indegree/outdegree with supplied edge count; no identity/composition category data. It returns a labeled HomFunctor, not an action on actual hom-sets. Two tests fully read, no execution.',
 'src/functor/functor.rs':'Complete211-line body read; tiny display-truncated test lines183-191 separately read. Public labeled pair-list shell checks nonempty strings only, not single-valued/total/lawful maps. FunctorIdentityCount separately checks a positive pair of equal supplied counts; it neither identifies concrete identities nor proves functor preservation. All tests read.',
 'src/functor/natural_transformation.rs':'Complete172-line body read. Labeled component pair-list shell expressly does not certify naturality. Separate OrdinalMap performs total lookup composition when every inner image indexes outer; arbitrary outer u32 values have no stored final codomain bound. This is useful sequence/function composition, not a natural transformation or endomap certificate. Empty sequences accepted where valid. Test read.',
 'src/functor/nat_trans_components.rs':'Complete175-line body read. Shell checks labels/nonempty tags; certify_components independently requires exact nonempty object coverage and injective component tags, but no component boundaries/naturality or shell validation. Global tag injectivity is a stricter metadata contract than ordinary natural transformations, which can reuse an arrow when functors identify objects. All tests read; the advertised injective-tag contract is explicit.',
 'src/functor/vertical_composition.rs':'Complete194-line body read. Shell records two references. VerticalAssocWitness checks all three arrays are permutations on a common nonempty finite ordinal, evaluates both association orders and compares every point. This genuinely verifies the supplied permutation composition equality, but is not bound to natural-transformation components or their referenced categories. Embedded tests read.',
 'src/functor/horizontal_composition.rs':'Complete124-line body read. Shell labels two natural-transformation references. GodementCountWitness validates labels, positive supplied component counts and checked-u64 multiplication only; it performs no Godement composition, boundary, interchange or naturality check. Tests are scalar12 and zero refusal. No execution.',
 'src/functor/hom_functor.rs':'Complete175-line body read. Shell validates nonempty references and a two-value variance tag. HomEndWitness separately checks label, variance and supplied count>=1; no actual hom-set, identity or functor action is represented. Positive endomorphism count is conditional arithmetic metadata. All tests read.',
 'src/functor/full_functor.rs':'Complete150-line body read. Fullness shell explicitly shape-only. Private witness checks image_homs=target_homs<=source_homs and stores the checked difference. Useful cardinality condition if values faithfully describe one real hom-map; no map, image-subset or complete hom-pair population is validated, and zero image/target is admitted. Tests read.',
 'src/functor/faithful_functor.rs':'Complete160-line body read. Shape-only reference shell. FaithfulOnHoms checks bounded object/arrow counts, endpoint ranges and no repeated (source,target,image-tag) triple. This establishes image-tag injectivity within supplied parallel-arrow rows, conditional on rows accurately representing all source arrows and a real functor; no category maps/laws are admitted. Empty arrow list allowed. Tests read.',
 'src/functor/essentially_surjective.rs':'Complete191-line body read. Reference shell is expressly shape-only. SkeletalCoverage checks a nonempty fixed-size array of present distinct in-range ordinal labels: a permutation, not essential surjectivity of a concrete functor. No target isomorphisms or image relation is supplied. Both positive and duplicate-preimage tests read.',
 'src/functor/constant_functor.rs':'Complete161-line body read. Shell validates four labels. ConstantImageWitness requires nonempty equal object-image integers and all supplied arrow-image integers zero; permits an empty arrow list and does not bind zero to an actual identity or integers to named carriers. Thus it certifies the stipulated encoding pattern only. All tests read.',
 'src/functor/diagonal_functor.rs':'Complete142-line body read. Shell requires arity>=2. DiagonalImageWitness computes checked base_objects^arity for positive base count. That is the full product carrier size; the diagonal image has base_objects elements, so image_slots must not be promoted into image cardinality. No tuples/maps/arrows are constructed. Unit tests explicitly expect3^2=9; no runtime execution.',
 'src/functor/forgetful_functor.rs':'Complete134-line body read. ForgetfulFunctor is a nonempty-label shell with no underlying-map construction. Separate LagrangeIndex multiplies positive subgroup_order and index with overflow refusal and a redundant division readback; there is no group, subgroup inclusion or coset witness. The integer product is useful metadata, not a proof of a named group theorem. Tests read.',
 'src/legacy_monad.rs':'Complete671-line body read. The private wrapper checks matching category name, all five underlying endofunctor predicates via typed violations, every unit/multiplication boundary, both naturalities and three monad equations. This is substantive conditional finite monad validation on an independently valid category. Category validity is not invoked; identity maps with unit/multiply e over the nonassociative unital magma pass its checked equations. Standalone law helpers skip missing entries; the aggregate boundary/functor checks discharge those omissions only on admitted carriers. ProfunctorMonad is a named record without actions/coend/law validation. Tests read, not executed.',
 'src/kleisli_category.rs':'Complete568-line body covered by residual reading plus exact capacity-block identifier-renaming comparison to fully read natural_trans.rs. Truncated display lines445-472 were separately read in full. Enumerates arrows A->T(B), adds unit identities and computes mu_C after T(g) after f. Collision guard refuses ambiguous formatted names despite comment claiming delimiter impossibility. Raw declaration is expressly unchecked; validated entry takes wrappers and validates every output category law. Monad wrapper stores no category snapshot, and this caller does not rebind it to the supplied category, so output category validity is stronger than provenance of the intended monad. Nerve construction only forwards a declaration to the separately pending nerve owner. All test bodies covered; no native execution.',
 'src/eilenberg_moore.rs':'Complete396-line body read. Generic Monad is an interface. Generic EMAlgebra::verify_laws and AlgebraMorphism::respects_algebras return true without invoking their defined sample closures or enumerating inputs. Forgetful and comparison maps return constant descriptive strings. MaybeMonad unit/bind/fmap and free action join are concrete; bool_em_algebra_holds explicitly checks all four double-Maybe bool shells for associativity, but does not itself check unit. Its original bool fixture covers both Just values. This narrow finite positive result does not repair generic placeholders. All tests and final exact four-case function read; no Rust execution.',
 'src/legacy_adjunction.rs':'Complete1117-line body read. Type-level markers and unconstrained Unit/Counit associated types are not certificates. Finite validator rebuilds functors from public legacy map copies, checks five functor predicates and two triangle equations, but omits unit/counit typing/naturality and category admission. Missing mapped unit/counit arrows skip triangles. S3 identity functors with noncentral inverse unit/counit satisfy triangles without naturality. DerivedMonad reads embedded maps, while validation reads legacy copies; DerivedComonad mixes them, allowing public divergence. Derived law helpers skip missing components and are conditional equation checks only. Kleisli lookup formula is useful on independently lawful total monad data. All duplicated comments, examples and capacity tests read; no original execution.',
 'src/hom_adjunction.rs':'Complete496-line body read. Each supplied witness checks exact forward domain/codomain against computed hom-sets and both inverse roundtrips; this is a meaningful local finite bijection predicate on admitted carriers. Validator does not require witnesses for every object pair, naturality in either variable, functor/category validity, functor name agreement or concrete object membership beyond object-map lookup. Empty witness vector returns an empty passing report. A C3 inversion bijection passes finite inverse checks but is not natural under identity functors. Three example tests and capacity boilerplate read, no native execution.',
 'src/natural_trans.rs':'Complete455-line body read. Traits and declared component map are separate from the private wrapper. Aggregate validator checks name agreement, components at every source object with target boundaries, and naturality equations for arrows whose two functor images are present. It does not validate the supplied categories or functors; missing arrow images are skipped, allowing identity components between incomplete singleton functor declarations. With independently valid categories and total lawful functors, the finite equations are useful. Extra component keys are ignored. Embedded naturality example and capacity tests read; no native execution.',
 'src/natural_trans_composition.rs':'Complete518-line body read. File-level cfg(any()) disables the entire module, with TODO legacy imports. Retained code builds identity components, vertical pointwise composition, left/right whiskering and horizontal composition comparing both paths. It operates on unchecked declarations and names, requiring external lawful-carrier/naturality premises; returned data is declared, not validated. Embedded four algebraic examples and separate capacity tests are also disabled. This is retained algorithm text, not an enabled implementation or executed result.',
 'Cargo.toml':'Complete95-line manifest read. Canonical lib.rs entry, edition2021, four declared dependency groups and19 explicit sibling integration-test targets; autotests=false. Comments mention stale src/mod.rs, which is absent at this snapshot. No Cargo resolution, build, test execution or sibling test-body credit.',
 'src/lib.rs':'Complete241-line entry read. Category/MorphismEq/Monoidal/Braided traits define callable interfaces, without enforcing associativity, unit, tensor or hexagon laws. Witness is a public name string; Law::check supplies an unconstrained result interface. Module exports are not dependency-body reading. IdentityArrowCensus private fields certify a nonempty permutation of0..n, with checked integer conversions/counting, but no categorical identity/composition relation. Embedded census tests exercise those finite integer predicates only.',
 'src/operad.rs':'Complete493-line body read. Typed named operations, explicit substitution table, declared identities, checked identity profiles/listed-entry typing/units. Constructor explicitly omits associativity; symmetry actions, equivariance, total substitution and membership of operation colors in the declared carrier are absent. Targeted associativity checks only supplied nested tuples; no parallel-slot law or complete enumeration. Added private BoundaryRecord enforces1<=items<=capacity, independent of operad semantics. Unit example and one nested associativity test plus count-bound tests read; no native execution.',
 'src/foundations/mod.rs':'Complete77-line foundation module read. Six reexported shell owners are separately reviewed in this report. CumulativeHLevelWitness compares supplied i8 labels with observed>=claimed, opposite the standard cumulative truncation-level implication; its groupoid-is-set test enshrines that reversal. Even a corrected inequality would remain a label check without a witness of a concrete type or its identity spaces.',
 'src/foundations/hlevel.rs':'Complete189-line body read. HLevel explicitly checks label and lower level bound only, with no concrete type witness. FiniteTruncation checks positive class sizes summing to at most32 supplied points: one singleton for Contractible, zero/one point for Proposition, arbitrary admitted partition sizes for Set. This is finite discrete cardinality data, not a general HoTT truncation/identity-space implementation. Tests inspected, not executed.',
 'src/foundations/finite_set.rs':'Complete246-line body read. Diagnostic string-vector shell requires nonempty tags and optional length agreement but does not deduplicate; cardinality means vector length. Separate private DisjointUnionCard checks intersection<=each side and exact checked-u64 inclusion-exclusion on supplied counts, with conservative overflow refusal before subtraction; it has no actual sets. Repeated capacity-bound record remains independent of these predicates. All embedded tests read.',
 'src/foundations/set.rs':'Complete168-line body read. Set explicitly says diagnostic inventory, not formal carrier; duplicate string tags are allowed and cardinality is vector length. Separate CardWitness genuinely treats supplied u32 slices as sets by sorting/deduplicating, computes union/intersection and checks inclusion-exclusion with overflow guards. The labeled shell and integer witness are not bound together. Tests read, not run.',
 'src/foundations/function.rs':'Complete234-line body read. Function checks labels/pair tags only, expressly not totality or single-valuedness. TotalFunction validates a separate nonempty finite ordinal map: exactly domain_size images, every image<codomain_size, exact distinct-image count. Shell pairs/carrier labels are not tied to the numeric map; resulting witness retains sizes/count only. Empty-domain functions are excluded by declared API. All tests read.',
 'src/foundations/truncation.rs':'Complete157-line body read. Shape shell explicitly does not implement a truncation HIT. TruncationWitness validates label, a present level and checked level+2 round trip; i32 intermediate overflow excludes the top two levels accepted by the shape shell. This is integer-offset metadata, with no type, universal property or path-space witness. Tests read.',
 'src/foundations/universe.rs':'Complete131-line body read. Universe checks label and stores level/cumulative flag; CumulativeUniverse checks two u64 counts in nondecreasing order and computes the difference. It represents neither concrete type inventories nor their embedding; checked_add(0) cannot add a new overflow condition. Count monotonicity does not establish actual inclusion, closure under type formation or a universe axiom. Tests read.',
 'src/finite_category.rs':'Complete408-line body read. Explicit finite object/morphism/identity/composition declarations use first-then-second table order; duplicate setters overwrite map entries. Validated wrapper owns a private declaration and invokes all owner checks; into_declared relinquishes the wrapper. Category-trait methods accept arbitrary Strings and panic on unknown object/morphism lookup, so callers still need membership preconditions. Data validation protects the retained declaration, not arbitrary names. Capacity witness is unrelated to categorical laws. All embedded tests and the separate trait owner read.',
 'src/finite_category_validation.rs':'Complete666-line body read. Eight checks cover key/name consistency and object references, nonempty names, total correctly typed identities, both identity laws, total composition on composable pairs, declared-arrow closure, absence of noncomposable/ill-typed composition entries and every composable triple associativity equation. Missing-data skips in individual checks are covered by the other mandatory checks. All eight units are always appended to a fresh report; empty category is allowed. Finite category axioms have an actual exhaustive predicate implementation here. Resource cost includes cubic morphism enumeration; no native execution or runtime-bound proof. Embedded positive/mutation tests fully read.',
 'src/validation.rs':'Complete449-line body read. Enum labels list obligations but do not implement them. Public mutable report/results aggregate supplied passed flags plus an empty typed-violation list; a newly empty report vacuously passes and payload messages can disagree with passed. This is bookkeeping, not self-authenticating evidence. The finite-category owner always supplies eight generated units, so empty-report behavior is not a bypass of its constructor. Warning/Info violations also fail add_typed. Capacity witness and embedded tests read; no runtime execution.',
 'src/cat_functor.rs':'Complete body read. Covariant/contravariant/category traits supply methods but encode no laws. DeclaredFiniteFunctor is public mutable data. Totality/boundary/composition helpers validate only caller-supplied source lists/tables, assuming those inventories are complete and categories valid. Identity helper constructs id_<object> strings instead of consulting category identity maps, so rejects a valid e->i singleton functor. No validated aggregate wrapper is present in this owner; later wrappers must be reviewed separately. All tests and capacity boilerplate read.',
 'src/functor/identity_functor.rs':'Complete220-line body read. Explicitly shape-only IdentityFunctor checks label/category_ref and contains no object or arrow map. IdentityLaw checks arrows>=objects and assigns identities=objects; it does not identify any identity arrow or check identity/functor laws. Count reconstruction is correct as arithmetic but needs a separate concrete category premise. Capacity witness and all tests read.',
 'src/limits_colimits/initial_object.rs':'Complete222-line body read. Shape shell checks three nonempty labels. InitialArrowFamily tests only aggregate arrows==targets; this cannot establish the claimed one-arrow-per-target property, because duplicate arrows to one object can mask missing arrows to another. A valid disjoint C2-plus-point category supplies outgoing counts(2,0) atA with total2 matching two objects. No concrete category or candidate-object binding in the numeric wrapper. All tests/capacity boilerplate read.',
 'src/functor_composition.rs':'Complete body read. Five actual-carrier functor checks cover totality, endpoints, actual identities and all listed compositions; identity naming flaw of legacy helper is absent. ValidatedFiniteFunctor clones private source/target declarations but does not validate them as categories; missing identities/compositions can be skipped. compose_validated_functors checks only middle category names, despite documented exact-match requirement, and returns a raw declaration without revalidation. Raw identity/opposite/inclusion/composition builders require lawful-carrier/revalidation premises; inclusion checks names/boundaries but not laws. All embedded tests/capacity boilerplate and the separate builder dependency read.',
 'src/finite_category_builder.rs':'Complete body read. Builder mutations make declarations; build returns them unchecked and build_validated calls the reviewed complete category validator. identity_checked verifies existing boundary only; identity_compositions inserts/overwrites forced unit entries for currently declared arrows and is not general composition completion. Walking-arrow builder is a concrete supported small construction when names are compatible. Capacity wrapper/tests remain unrelated to category-law evidence; all embedded test bodies read, no native run.',
}
file_reviews=[]
for name,note in notes.items():
    path=base+name;assert sha(ROOT/path)==by[path]['sha256']
    file_reviews.append({'path':path,'sha256':by[path]['sha256'],'full_source_read':True,
                         'reviewed_lines':[[1,len((ROOT/path).read_text().splitlines())]],
                         'review_level':'full_source_body_review','assessment':note})
transfer_path=REV/(PREFIX+'_reading_transfers.json')
transfers=json.loads(transfer_path.read_text()) if transfer_path.exists() else []
def normalize_capacity(lines):
    return re.sub(r'(?<=BoundaryRecord)[0-9a-f]{8}|(?<=BoundaryError)[0-9a-f]{8}|(?<=l4_boundary_tests_)[0-9a-f]{8}', 'HASH', '\n'.join(lines)).rstrip()
full_by_path={r['path']:r for r in file_reviews}
for receipt in transfers:
    if receipt['path'] not in full_by_path:continue
    target=(ROOT/receipt['path']).read_text().splitlines();covered=set(receipt['displayed_residual_line_numbers'])
    assert receipt['sha256']==by[receipt['path']]['sha256'] and receipt['lines']==len(target)
    for block in receipt['transfers']:
        assert block['base_path'] in full_by_path and sha(ROOT/block['base_path'])==block['base_sha256']
        baseline=(ROOT/block['base_path']).read_text().splitlines();a,z=block['base_lines'];ta,tz=block['target_lines']
        assert 1<=a<=z<=len(baseline) and 1<=ta<=tz<=len(target)
        body=normalize_capacity(target[ta-1:tz]);assert body==normalize_capacity(baseline[a-1:z])
        assert hashlib.sha256(body.encode()).hexdigest()==block['normalized_sha256']
        covered.update(range(ta,tz+1))
    assert covered==set(range(1,len(target)+1))
    full_by_path[receipt['path']]['reading_method']='Complete residual body and separately verified repeated capacity blocks; contextual assessment above, no automated semantic inference.'
    full_by_path[receipt['path']]['reading_transfer_ledger']='dag/reviews/'+PREFIX+'_reading_transfers.json'
def ev(name,lo,hi):return {'path':base+name,'sha256':by[base+name]['sha256'],'lines':[[lo,hi]]}
