def normalize_delegate(value):
    if isinstance(value,list):return [normalize_delegate(v) for v in value]
    if not isinstance(value,dict):return value
    value={k:normalize_delegate(v) for k,v in value.items()}
    if {'path','sha256','lines'}<=value.keys() and len(value['lines'])==2 and all(isinstance(x,int) for x in value['lines']):
        value['lines']=[value['lines']]
    return value
