checked=[]
def validate_ranges(value):
    if isinstance(value,dict):
        if {'path','sha256','lines'}<=value.keys():
            raw=(ROOT/value['path']).read_bytes();assert hashlib.sha256(raw).hexdigest()==value['sha256']
            n=len(raw.decode().splitlines())
            for a,z in value['lines']:
                assert 1<=a<=z<=n
                checked.append((value['path'],a,z))
        for v in value.values():validate_ranges(v)
    elif isinstance(value,list):
        for v in value:validate_ranges(v)
